function printReadiness(work=studio){
 if(work.layers>=5)return {ready:false,kind:'complete',text:'✓ All five impressions are complete. Continue to reveal your painting.'};
 if(work.block!==work.layers)return {ready:false,kind:'sequence',text:'Choose the next block in sequence before printing. Your paper is unchanged.'};
 if(Math.abs(work.offsetX)>4||Math.abs(work.offsetY)>4)return {ready:false,kind:'alignment',text:'＋ Needs alignment. Move the dashed outline onto the fixed guides, or choose Align to guides.'};
 return {ready:true,kind:'ready',text:'✓ Ready to print. The block is aligned with the paper.'};
}
function updatePrintReadiness(){
 const state=printReadiness(),pressButton=$('#press'),status=$('#alignment-status');
 if(pressButton)pressButton.disabled=!!printPressAction||!state.ready;
 if(status){if(status.textContent!==state.text)status.textContent=state.text;status.dataset.state=state.kind;}
 $('#alignment-block')?.classList.toggle('is-aligned',state.ready);
 $$('[data-move],#align').forEach(button=>button.disabled=!!printPressAction||studio.layers>=5);
}
function printWorkspace(){
 const a=artwork[studio.art],ps=pigments(),state=printReadiness(),done=studio.layers>=5;
 return `<div class="work-title"><div><h2>One impression at a time.</h2><p>${done?'All five impressions are complete. Your painting is ready to reveal.':'Select a block, align the guides, then press to transfer the color.'}</p></div><span class="micro">${a.en} · ${studio.layers}/5 layers</span></div>
 <div class="print-workspace">
  <div class="print-visual"><div class="printing-table" id="printing-table" tabindex="0" role="group" aria-label="Alignment area. Drag to move the block, use arrow keys to adjust, and Enter to print." aria-describedby="alignment-help alignment-status">
   <div class="registration-surface"><div class="print-paper"><canvas id="print-canvas" width="900" height="600" role="img" aria-label="${esc(a.en)} — ${studio.layers}/5 color layers printed"></canvas></div>
    <div id="press-block" class="press-block" aria-hidden="true" hidden><span class="press-block-handle"></span></div>
    <div class="registration-target" aria-hidden="true" ${done?'hidden':''}></div>
    <div class="alignment-block ${state.ready?'is-aligned':''}" id="alignment-block" aria-hidden="true" style="transform:translate(${studio.offsetX}px,${studio.offsetY}px)" ${done?'hidden':''}></div>
   </div></div><p class="registration-legend"><span>└ ┐ Fixed paper guides</span><span>┄ Moving block outline</span></p>
  </div>
  <div class="print-controls"><div class="eyebrow">Your printing blocks</div>
   <div class="block-choices">${ps.map((p,i)=>`<button class="block-choice ${studio.block===i?'active':''}" data-block="${i}" aria-pressed="${studio.block===i}" ${i<studio.layers||(studio.mode==='guided'&&i!==studio.layers)?'disabled':''}><span class="dot" style="background:${p.color}"></span>${i<studio.layers?'✓ ':''}${p.name}</button>`).join('')}</div>
   <h3>${done?'The story comes together.':ps[studio.block].name}</h3><p>${done?'Color areas and black contours have joined to form your finished study.':ps[studio.block].body}</p>
   <div class="print-action-group"><p class="alignment-status" id="alignment-status" data-state="${state.kind}" role="status">${state.text}</p>
    <p class="instruction" id="alignment-help">Drag the block on the table, or use these controls. Match the fixed corners within 4 px. <span id="offset-label">X: ${studio.offsetX}, Y: ${studio.offsetY}</span></p>
    <div class="align-controls" role="group" aria-label="Align the printing block">
     <button id="align" ${done?'disabled':''}>Align to guides</button>
     <div class="alignment-arrows">${[['left','←'],['up','↑'],['down','↓'],['right','→']].map(([dir,label])=>`<button data-move="${dir}" aria-label="Move ${dir} 2 pixels" ${done?'disabled':''}>${label}</button>`).join('')}</div>
    </div>
    <button class="btn" id="press" aria-describedby="alignment-status" ${state.ready?'':'disabled'}>Press &amp; lift the block ↓</button>
    <button class="undo" id="undo" ${!studio.layers?'disabled':''}>↶ Undo last impression</button>
   </div>
   <div class="progress" role="progressbar" aria-valuenow="${studio.layers}" aria-valuemin="0" aria-valuemax="5" aria-label="Printed layers"><span style="width:${studio.layers*20}%"></span></div><span class="micro">${studio.layers} / 5 impressions complete</span>
   <p id="print-feedback" class="feedback" role="status">${done?'✓ All layers printed. Continue to reveal your painting.':''}</p>
   ${studio.mode==='guided'?'<div class="hint">Each block adds one part of the picture. Alignment helps the colors meet the final black contours.</div>':''}
  </div>
 </div>`;
}
let printPressAction=null;
function loadPrintImage(key,layers){
 const cacheKey=key+':'+layers;
 if(!printImageCache.has(cacheKey)){
  const image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(window.PrintLayers.svgForStage(ART_DATA[key],layers));
  printImageCache.set(cacheKey,image.decode().then(()=>image).catch(error=>{printImageCache.delete(cacheKey);throw error;}));
 }
 return printImageCache.get(cacheKey);
}
function cancelPrintPress(){
 const action=printPressAction;if(!action)return;
 printPressAction=null;
 for(const timer of action.timers)clearTimeout(timer);
 action.media?.removeEventListener?.('change',action.motionChange);
 if(action.overlay){action.overlay.hidden=true;action.overlay.dataset.phase='';}
 action.table?.setAttribute('aria-busy','false');
 action.resolve?.();
}
function printPressMatches(action){
 return printPressAction===action&&studio.art===action.art&&studio.layers===action.layers+(action.committed?1:0)&&$('#print-canvas')===action.target&&action.target.isConnected;
}
function lockPrintPress(){
 $$('[data-block],[data-move],#align,#press,#undo').forEach(button=>button.disabled=true);
 for(const id of ['#align','#press','#undo'])if($(id))$(id).disabled=true;
 $('#printing-table')?.setAttribute('aria-busy','true');
}
function commitPrintPress(action){
 if(action.committed||!printPressMatches(action))return;
 action.committed=true;studio.layers=action.layers+1;studio.block=Math.min(4,studio.layers);studio.offsetX=12;studio.offsetY=-8;persistStudio();
 printDrawVersion++;
 const ctx=action.target.getContext('2d');ctx.clearRect(0,0,action.target.width,action.target.height);ctx.drawImage(action.image,0,0,action.target.width,action.target.height);
}
function finishPrintPress(action){
 if(!printPressMatches(action)){if(printPressAction===action)cancelPrintPress();return;}
 commitPrintPress(action);
 const feedback=pigments()[action.block].name+' transferred · '+studio.layers+' of 5.'+(studio.layers===5?' The black contours complete your print. Ready for the reveal.':'');
 cancelPrintPress();render(studio.layers===5?'#continue':'#align');
 if($('#print-feedback'))$('#print-feedback').textContent=feedback;
}
async function startPrintPress(){
 const action={art:studio.art,block:studio.block,layers:studio.layers,target:$('#print-canvas'),overlay:$('#press-block'),table:$('#printing-table'),timers:[],committed:false};
 printPressAction=action;lockPrintPress();$('#print-feedback').textContent='Preparing the block…';
 try{action.image=await loadPrintImage(action.art,action.layers+1);}catch{
  if(printPressAction===action){cancelPrintPress();render('#press');$('#print-feedback').textContent='The next impression could not load. Your paper is unchanged. Press again to retry.';}return;
 }
 if(!printPressMatches(action)){if(printPressAction===action)cancelPrintPress();return;}
 action.media=window.matchMedia?.('(prefers-reduced-motion: reduce)');
 if(action.media?.matches||document.body.classList.contains('motion-paused')){finishPrintPress(action);return;}
 return new Promise(resolve=>{
  action.resolve=resolve;
  const phase=(name,text)=>{action.overlay.hidden=false;action.overlay.dataset.phase=name;$('#print-feedback').textContent=text;};
  const schedule=(delay,fn)=>action.timers.push(setTimeout(()=>{if(printPressMatches(action))fn();else if(printPressAction===action)cancelPrintPress();},delay));
  action.motionChange=event=>{if(event.matches)finishPrintPress(action);};action.media?.addEventListener?.('change',action.motionChange);
  phase('lowering','Lowering block…');
  schedule(250,()=>{commitPrintPress(action);phase('pressing','Pressing…');});
  schedule(550,()=>phase('lifting','Lifting the block…'));
  schedule(1000,()=>finishPrintPress(action));
 });
}
;
