(() => {
 let cleanup=()=>{};
 function mount(){
  cleanup();
  const header=document.querySelector('.site-header'),menu=document.querySelector('#menu'),nav=document.querySelector('#site-navigation');
  if(!header||!menu||!nav)return;
  const viewport=window.matchMedia?.('(max-width: 1199px)');
  const measure=()=>document.documentElement.style.setProperty('--site-header-height',Math.ceil(header.getBoundingClientRect().height)+'px');
  const close=(focus=false)=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');if(focus)menu.focus({preventScroll:true});};
  menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');};
  const keydown=event=>{if(event.key==='Escape'&&nav.classList.contains('open')){event.preventDefault();close(true);}};
  const resize=()=>{if(!viewport?.matches)close();measure();};
  const revealFocus=event=>{
   if(header.contains(event.target)||event.target.closest?.('dialog'))return;
   const rect=event.target.getBoundingClientRect?.(),offset=header.getBoundingClientRect().height+16;
   const dock=document.querySelector('#drawing-actions');
   if(dock?.contains(event.target))return;
   const bottom=dock?dock.getBoundingClientRect().top-16:window.innerHeight;
   if(rect?.height&&rect.top<offset)window.scrollBy?.({top:rect.top-offset,behavior:'instant'});
   else if(rect?.height&&rect.bottom>bottom)window.scrollBy?.({top:Math.min(rect.bottom-bottom,rect.top-offset),behavior:'instant'});
  };
  header.addEventListener('keydown',keydown);document.addEventListener('focusin',revealFocus);
  window.addEventListener('resize',resize);viewport?.addEventListener?.('change',resize);
  const observer=typeof window.ResizeObserver==='function'?new window.ResizeObserver(measure):null;
  observer?.observe(header);measure();
  cleanup=()=>{observer?.disconnect();header.removeEventListener('keydown',keydown);document.removeEventListener('focusin',revealFocus);window.removeEventListener('resize',resize);viewport?.removeEventListener?.('change',resize);menu.onclick=null;};
 }
 window.SiteShell={mount,destroy(){cleanup();cleanup=()=>{};}};
})();
;
