function heritageIllustration(chapter){
 const block=`<div class="heritage-woodblock"><img src="assets/mouse.svg" width="900" height="600" alt="Mouse Wedding study reproduced as a teaching woodblock illustration"></div>`;
 if(chapter.image==='village')return `<div class="heritage-visual visual-village">${village}<span class="visual-imprint">A VILLAGE. A SHARED PRACTICE.</span></div>`;
 if(chapter.image==='chickens')return `<div class="heritage-visual visual-newyear">${img('chickens')}<span class="visual-imprint">A PICTURE. A WISH FOR THE YEAR.</span></div>`;
 if(chapter.image==='materials')return `<div class="heritage-visual visual-materials"><div class="material-sheets"><span></span><span></span><span></span></div><div class="heritage-pigments" aria-hidden="true">${['#b74732','#58734d','#d5a24b','#f8f1db','#292620'].map(c=>`<i style="background:${c}"></i>`).join('')}</div><span class="visual-imprint">PAPER / PIGMENT / IMPRESSION</span></div>`;
 if(chapter.image==='blocks')return `<div class="heritage-visual visual-blocks">${block}<span class="visual-imprint">TOOLS CARRY STORIES, TOO.</span></div>`;
 if(chapter.image==='gallery')return `<div class="heritage-visual visual-gallery"><div class="mini-exhibition">${img('pigs')}${img('mouse')}${img('chickens')}</div><span class="visual-imprint">BEHIND EVERY PRINT, A MAKER.</span></div>`;
 return `<div class="heritage-visual visual-future"><div class="future-print">${img('pigs')}</div><div class="future-label"><b>2012</b><i></i><b>2025</b><i></i><span>ONWARD</span></div><span class="visual-imprint">RECOGNITION IS A BEGINNING.</span></div>`;
}
function heritageSourceLinks(ids){return ids.map(id=>{const s=HERITAGE_SOURCES[id];return `<li><a href="${s.url}" target="_blank" rel="noopener">${s.title} <span aria-hidden="true">↗</span></a><span>${s.publisher} · ${s.date}</span></li>`;}).join('');}
;
