function readerIcon(kind){const paths={book:'<path d="M3 5q4-2 8 0v14q-4-2-8 0Zm18 0q-4-2-8 0v14q4-2 8 0Z"/>',play:'<path d="m8 4 12 8-12 8Z"/>',pause:'<path d="M8 5v14m8-14v14"/>',stop:'<path d="M6 6h12v12H6Z"/>',sources:'<path d="M6 3h9l4 4v14H6ZM14 3v5h5M9 12h7m-7 4h7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',sound:'<path d="m4 9 5 0 5-4v14l-5-4H4Zm13-1q5 4 0 8"/>',chevron:'<path d="m7 9 5 5 5-5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths[kind]||paths.book}</g></svg>`;}
function chapterBookmarks(mobile=false){return histories().map((c,i)=>`<button ${mobile?'':`id="history-tab-${i}" role="tab" aria-selected="${i===historyIndex}" aria-controls="history-panel" tabindex="${i===historyIndex?0:-1}"`} data-history="${i}" class="chapter-bookmark ${i===historyIndex?'active':''}" ${mobile?`aria-current="${i===historyIndex?'step':'false'}"`:''}><span class="bookmark-number">${String(i+1).padStart(2,'0')}</span><span><strong>${c.short}</strong><small>${c.period}</small></span></button>`).join('');}
function historySourceDialog(c){const all=Object.keys(HERITAGE_SOURCES).filter(id=>!c.sources.includes(id));return `<dialog id="history-sources" class="reader-dialog" aria-labelledby="history-sources-title"><div class="reader-dialog-top"><span>THE NOTES BEHIND THE STORY</span><button id="close-history-sources" class="reader-close" aria-label="Close sources">${readerIcon('close')}</button></div><section id="sources"><div class="reader-source-heading"><span>Chapter ${historyIndex+1}</span><h2 id="history-sources-title">Sources & a few<br><em>important distinctions.</em></h2><p>${c.title}</p></div><h3>For this chapter</h3><ul class="reader-source-list">${heritageSourceLinks(c.sources)}</ul><div class="reader-source-note"><h3>About the illustration</h3><p>${c.imageNote}</p><p>The village scenes, example paintings, and objects are contemporary vector study reconstructions. No source photographs or official emblems have been reproduced. Visitor drawings are original contemporary creations.</p><h3>History and interpretation</h3><p>${c.kind}. Source publication dates belong to their reports; older household or lineage counts are not a current census. Symbolic meanings are common interpretations rather than fixed historical events.</p><h3>About the digital workshop</h3><p>The printing lesson uses reconstructed color masks, not recovered original blocks. It demonstrates successive colors and a final black outline, with a disclosed green-toned substitute for a blue reference stage. Recipes, blocks, and working methods vary.</p></div><h3>Across the exhibition</h3><ul class="reader-source-list">${heritageSourceLinks(all)}</ul><div class="reader-archival-links"><h3>Compare archival examples</h3><a href="https://commons.wikimedia.org/wiki/File:%C4%90%C3%A1m_c%C6%B0%E1%BB%9Bi_chu%E1%BB%99t.JPG" target="_blank" rel="noopener">Mouse Wedding ↗</a><a href="https://commons.wikimedia.org/wiki/File:L%E1%BB%A3n_%C3%A2m_d%C6%B0%C6%A1ng.JPG" target="_blank" rel="noopener">Yin-Yang Pig Family ↗</a><a href="https://commons.wikimedia.org/wiki/File:S%C3%A2n_g%C3%A0.JPG" target="_blank" rel="noopener">Hen and Chicks ↗</a></div><p class="reader-research-date">Research checked 5 November 2026.</p></section></dialog>`;}
function historyListeningBar(){return `<div id="history-listening" class="history-listening" ${historyReader.mode==='listen'?'':'hidden'}><span class="reader-audio-emblem" aria-hidden="true">${readerIcon('sound')}</span><div class="reader-audio-copy"><strong id="reader-audio-status" role="status">Ready whenever you are.</strong><span>The story below is also your full transcript.</span></div><button id="reader-playback" class="reader-playback" aria-label="Play chapter narration">${readerIcon('play')}</button><button id="reader-stop" class="reader-stop" aria-label="Stop chapter narration" hidden>${readerIcon('stop')}</button><button id="reader-follow" class="reader-follow">Follow the words <span aria-hidden="true">↓</span></button></div>`;}
function heritagePage(){
 const chapters=histories();historyIndex=Number.isInteger(historyIndex)?Math.max(0,Math.min(chapters.length-1,historyIndex)):0;const c=chapters[historyIndex];
 return `<main id="main" class="wrap storybook-page"><section class="storybook-heading"><div class="eyebrow">The living history of Dong Ho</div><h1>Some stories<br><em>are still being made.</em></h1><p>Six chapters, a village, and generations of hands. Take your time with the story—or let it come to you in a voice.</p></section><div class="storybook-layout"><nav class="storybook-bookmarks" role="tablist" aria-label="History chapters" aria-orientation="vertical"><span class="bookmarks-label">THE CHAPTERS</span>${chapterBookmarks()}</nav><div class="storybook-content"><button id="open-chapter-chooser" class="mobile-chapter-chooser" aria-haspopup="dialog" aria-controls="chapter-chooser"><span><small>CHAPTER ${historyIndex+1} OF ${chapters.length}</small><strong>${c.short}</strong></span>${readerIcon('chevron')}</button><section id="history-panel" class="storybook-chapter fade-in" role="tabpanel" aria-labelledby="chapter-title"><figure class="storybook-illustration">${heritageIllustration(c)}<figcaption>${c.imageNote}</figcaption></figure><div class="storybook-opening"><div class="storybook-chapter-label"><span>CHAPTER ${String(historyIndex+1).padStart(2,'0')}</span><i aria-hidden="true"></i><span>${c.period}</span></div><h2 id="chapter-title" tabindex="-1">${c.title}</h2></div><div class="reader-toolbar" role="group" aria-label="Read, listen, or explore sources"><button id="reader-read" class="reader-mode ${historyReader.mode==='read'?'active':''}" aria-pressed="${historyReader.mode==='read'}">${readerIcon('book')} Read</button><button id="reader-listen" class="reader-mode ${historyReader.mode==='listen'?'active':''}" aria-pressed="${historyReader.mode==='listen'}">${readerIcon('sound')} Listen</button><button id="reader-sources" class="reader-sources" data-reader-sources aria-haspopup="dialog" aria-controls="history-sources">${readerIcon('sources')} Sources</button></div>${historyListeningBar()}<article id="chapter-words" class="storybook-words" tabindex="-1" aria-label="Full story and narration transcript"><p class="storybook-intro">${c.intro}</p><div class="storybook-body">${c.deeper.map(p=>`<p>${p}</p>`).join('')}</div></article><p class="storybook-evidence"><span aria-hidden="true">✦</span>${c.kind}</p><div class="storybook-reflection"><span aria-hidden="true">✳</span><div><small>A MOMENT TO WONDER</small><p>${c.reflection}</p></div></div><div class="storybook-next-action">${c.action.chapter!==undefined?`<button class="text-link" data-chapter-jump="${c.action.chapter}">${c.action.label} →</button>`:`<a class="text-link" href="${c.action.href}" ${c.action.mode?`data-history-mode="${c.action.mode}"`:''}>${c.action.label} ↗</a>`}</div></section><nav class="storybook-pagination" aria-label="Continue through history"><button id="previous-history" ${historyIndex===0?'disabled':''}><span aria-hidden="true">←</span><span>Previous chapter</span></button><span class="storybook-page-number">${String(historyIndex+1).padStart(2,'0')}<i></i>${String(chapters.length).padStart(2,'0')}</span><button id="next-history"><span>${historyIndex===chapters.length-1?'Back to the beginning':'Next chapter'}</span><span aria-hidden="true">→</span></button></nav><section class="storybook-outro"><span class="eyebrow">The story does not stop here</span><h2>Let a little of it<br><em>find its way into your hands.</em></h2><a class="btn" data-create-free href="WorkshopPage.html">Create your own response ↗</a></section></div></div>${historySourceDialog(c)}<dialog id="chapter-chooser" class="reader-dialog chapter-chooser-dialog" aria-labelledby="chapter-chooser-title"><div class="reader-dialog-top"><span>FOLLOW YOUR CURIOSITY</span><button id="close-chapter-chooser" class="reader-close" aria-label="Close chapter chooser">${readerIcon('close')}</button></div><h2 id="chapter-chooser-title">Where shall<br><em>we begin?</em></h2><nav class="mobile-chapter-list" aria-label="Choose a history chapter">${chapterBookmarks(true)}</nav></dialog></main>`;
}
function updateHistoryVoice(state){
 historyReader.voice=state;const playback=$('#reader-playback'),status=$('#reader-audio-status'),stop=$('#reader-stop');if(!playback||!status)return;
 const playing=state==='playing',paused=state==='paused';playback.innerHTML=readerIcon(playing?'pause':'play');playback.setAttribute('aria-label',playing?'Pause chapter narration':paused?'Resume chapter narration':'Play chapter narration');
 if(stop)stop.hidden=!playing&&!paused;
 status.textContent=playing?'A story, told at your pace.':paused?'A little pause. Continue when you like.':state==='ended'?'That chapter has left its impression.':state==='unavailable'?'The voice is unavailable. Every word is here to read.':'Ready whenever you are.';
}
function startHistoryNarration(){const c=histories()[historyIndex];const started=speak([`Chapter ${historyIndex+1}. ${c.title}.`,c.intro,...c.deeper].join(' '),{onState:updateHistoryVoice});if(!started)updateHistoryVoice('unavailable');}
function setHistoryReadingMode(mode){if(mode==='listen'&&historyReader.mode==='listen'&&['playing','paused'].includes(historyReader.voice))return;historyReader.mode=mode;$('#history-listening').hidden=mode!=='listen';for(const [id,value] of [['reader-read','read'],['reader-listen','listen']]){const button=$('#'+id);button.classList.toggle('active',mode===value);button.setAttribute('aria-pressed',String(mode===value));}if(mode==='read')stopSpeech();else startHistoryNarration();}
function openHistorySources(opener){if(historyReader.voice==='playing')pauseSpeech();historySourcesReturn=opener||$('#reader-sources');$('#history-sources').showModal();$('#close-history-sources').focus({preventScroll:true});}
function closeHistorySources(){$('#history-sources').close();}
function bindReaderDialog(dialog,close,restore){close.onclick=()=>dialog.close();dialog.addEventListener('close',()=>restore()?.focus({preventScroll:true}));dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();});}
function selectHeritageChapter(index,focus,showStory=false){
 stopSpeech();historyReader.mode='read';historyReader.voice='idle';historyIndex=Math.max(0,Math.min(histories().length-1,index));save('dongho-history-chapter',historyIndex);render(focus||'#history-tab-'+historyIndex);
 if(showStory)$('#history-panel')?.scrollIntoView?.({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
}
function bindHeritage(){
 $$('[data-history]').forEach(button=>button.onclick=()=>selectHeritageChapter(Number(button.dataset.history),button.closest?.('.mobile-chapter-list')?'#chapter-title':null,true));
 $('#next-history').onclick=()=>selectHeritageChapter((historyIndex+1)%histories().length,'#chapter-title',true);$('#previous-history').onclick=()=>selectHeritageChapter(historyIndex-1,'#chapter-title',true);
 $$('[data-chapter-jump]').forEach(button=>button.onclick=()=>selectHeritageChapter(Number(button.dataset.chapterJump),'#chapter-title',true));
 $$('[data-history-mode]').forEach(link=>link.onclick=()=>{creationMode=link.dataset.historyMode;save('dongho-creation-mode',creationMode);});$$('[data-create-free]').forEach(link=>link.onclick=()=>{creationMode='free';save('dongho-creation-mode','free');});
 $('#reader-read').onclick=()=>setHistoryReadingMode('read');$('#reader-listen').onclick=()=>setHistoryReadingMode('listen');$('#reader-playback').onclick=()=>{if(historyReader.voice==='playing')pauseSpeech();else if(historyReader.voice==='paused')resumeSpeech();else startHistoryNarration();};$('#reader-stop').onclick=stopSpeech;
 $('#reader-follow').onclick=()=>{const words=$('#chapter-words');words.scrollIntoView({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});words.focus({preventScroll:true});};
 $$('[data-reader-sources]').forEach(button=>button.onclick=()=>openHistorySources(button));
 bindReaderDialog($('#history-sources'),$('#close-history-sources'),()=>historySourcesReturn);
 $('#open-chapter-chooser').onclick=()=>{if(historyReader.voice==='playing')pauseSpeech();historyChaptersReturn=$('#open-chapter-chooser');$('#chapter-chooser').showModal();$('#close-chapter-chooser').focus({preventScroll:true});};bindReaderDialog($('#chapter-chooser'),$('#close-chapter-chooser'),()=>historyChaptersReturn);
 $$('[data-history][role="tab"]').forEach(button=>button.addEventListener('keydown',event=>{const items=$$('[data-history][role="tab"]'),i=items.indexOf(button);let next;if(['ArrowDown','ArrowRight'].includes(event.key))next=(i+1)%items.length;else if(['ArrowUp','ArrowLeft'].includes(event.key))next=(i-1+items.length)%items.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=items.length-1;else return;event.preventDefault();selectHeritageChapter(Number(items[next].dataset.history));}));
 updateHistoryVoice(historyReader.voice);
}
