function paintDrawingCanvas(canvas,record,pending=null){if(!canvas)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,DRAW_WIDTH,DRAW_HEIGHT);record.strokes.forEach(s=>strokeToContext(ctx,s));if(pending)strokeToContext(ctx,pending);}
