function storeDrawingDraft(){cancelDrawingMetadataSave();const stored=save('dongho-drawing-draft',drawingDraft);const status=$('#drawing-status');if(status)status.textContent=stored?t('Draft saved on this device.','Đã lưu bản nháp trên thiết bị.'):t('Draft kept for this session. Download a PNG to keep it.','Giữ bản nháp trong phiên này. Tải PNG để lưu lại.');updateDrawingControls();}
function updateDrawingControls(){const title=$('#drawing-current-title');if(title)title.textContent=drawingDraft.title.trim()||'Untitled artwork';const n=drawingDraft.strokes.length;$('#drawing-empty')?.toggleAttribute('hidden',n>0||!!activeStroke);if($('#draw-undo'))$('#draw-undo').disabled=!drawUndo.length;if($('#draw-redo'))$('#draw-redo').disabled=!drawRedo.length;for(const id of ['#draw-clear','#draw-download'])if($(id))$(id).disabled=!n;const link=$('#draw-exhibit');if(link){link.classList.toggle('disabled-link',!n);link.setAttribute('aria-disabled',String(!n));}if($('#drawing-count'))$('#drawing-count').textContent=n+' '+t('strokes','nét vẽ');}
function finishDrawingStroke(){if(!activeStroke)return;rememberDrawing();cacheCompletedDrawingStroke(activeStroke);drawingDraft.strokes.push(activeStroke);activeStroke=null;keyboardPen=false;storeDrawingDraft();if($('#drawing-canvas'))repaintDrawing();}
function drawingUndo(){finishDrawingStroke();if(!drawUndo.length)return;drawRedo.push(drawingDraft.strokes.slice());drawingDraft.strokes=drawUndo.pop();storeDrawingDraft();repaintDrawing();}
