let drawingRaster=null,drawingRasterStrokes=null,drawingRasterCount=0;
let drawingMetadataTimer=0,drawingMetadataDirty=false,drawingPaintVersion=0;
let unbindDrawingRuntime=()=>{};
function ensureDrawingRaster(){
 if(!drawingRaster){drawingRaster=document.createElement('canvas');drawingRaster.width=DRAW_WIDTH;drawingRaster.height=DRAW_HEIGHT;}
 if(drawingRasterStrokes!==drawingDraft.strokes||drawingRasterCount!==drawingDraft.strokes.length){
  paintDrawingCanvas(drawingRaster,drawingDraft);
  drawingRasterStrokes=drawingDraft.strokes;drawingRasterCount=drawingDraft.strokes.length;
 }
 return drawingRaster;
}
function cacheCompletedDrawingStroke(stroke){
 const raster=ensureDrawingRaster();strokeToContext(raster.getContext('2d'),stroke);drawingRasterCount++;
}
function paintCachedDrawing(){
 const canvas=$('#drawing-canvas');if(!canvas||!drawingDraft)return;
 const raster=ensureDrawingRaster(),ctx=canvas.getContext('2d');
 ctx.clearRect(0,0,DRAW_WIDTH,DRAW_HEIGHT);ctx.drawImage(raster,0,0);
 if(activeStroke)strokeToContext(ctx,activeStroke);
}
function cancelDrawingMetadataSave(){clearTimeout(drawingMetadataTimer);drawingMetadataTimer=0;drawingMetadataDirty=false;}
function queueDrawingMetadataSave(){
 memoryState['dongho-drawing-draft']=drawingDraft;
 drawingMetadataDirty=true;clearTimeout(drawingMetadataTimer);
 drawingMetadataTimer=setTimeout(flushDrawingMetadata,300);
 updateDrawingControls();const status=$('#drawing-status');if(status)status.textContent='Saving draft…';
}
function flushDrawingMetadata(){if(drawingMetadataDirty)storeDrawingDraft();}
function bindDrawingRuntime(){
 unbindDrawingRuntime();
 const leave=()=>{finishDrawingStroke();flushDrawingMetadata();};
 const visibility=()=>{if(document.visibilityState==='hidden')leave();};
 const followLink=event=>{if(event.target.closest?.('a[href]'))leave();};
 window.addEventListener('pagehide',leave);
 document.addEventListener?.('visibilitychange',visibility);
 for(const type of ['click','auxclick','contextmenu'])document.addEventListener?.(type,followLink,true);
 unbindDrawingRuntime=()=>{
  window.removeEventListener?.('pagehide',leave);document.removeEventListener?.('visibilitychange',visibility);
  for(const type of ['click','auxclick','contextmenu'])document.removeEventListener?.(type,followLink,true);
  unbindDrawingRuntime=()=>{};
 };
}
function disposeDrawingRuntime(){
 finishDrawingStroke();flushDrawingMetadata();unbindDrawingRuntime();
 drawingPaintVersion++;if(drawFrame)window.cancelAnimationFrame?.(drawFrame);drawFrame=0;
 drawingRaster=null;drawingRasterStrokes=null;drawingRasterCount=0;
}
;
