function shopStudySvg(id,step){
 const reference=shopDrawingReference(id),parts=shopStudyParts(id);
 if(!reference||!parts||!Number.isInteger(step)||step<0||step>4)return '';
 const mono=markup=>markup.replace(/fill="#[a-f0-9]{6}"/gi,'fill="#f8f1db"').replace(/stroke="#[a-f0-9]{6}"/gi,'stroke="#62584d"');
 const label=inspirationEscape(`${reference.title} - simplified drawing study, step ${step+1}: ${reference.steps[step].summary}`);
 const layer=(name,markup)=>`<g data-study-part="${name}">${step<3?mono(markup):markup}</g>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${parts.width} ${parts.height}" role="img" aria-label="${label}"><title>${label}</title><rect width="${parts.width}" height="${parts.height}" fill="#f8f1db"/><g fill="none" stroke="#292620" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">${step===0?`<g data-study-part="composition" stroke="#62584d" stroke-dasharray="7 6">${parts.composition}</g>`:layer('silhouettes',parts.silhouettes)}${step>=2?layer('support',parts.support):''}${step===4?`<g data-study-part="details" stroke-width="1.8">${parts.details}</g>`:''}</g></svg>`;
}
