let disposeReferenceViewer=()=>{};
function drawingPhotoReference(id){return shopDrawingReference(id)||traditionalReference(id);}
function drawingPhotoMarkup(reference){
 return `<figure class="museum-reference"><img src="${reference.image}" width="${reference.width}" height="${reference.height}" alt="${reference.alt}" decoding="async"><figcaption><strong>${reference.title}</strong></figcaption><button id="enlarge-reference" class="guide-preset" aria-haspopup="dialog" aria-controls="reference-viewer">Enlarge reference <span aria-hidden="true">↗</span></button></figure>`;
}
function referenceViewerMarkup(){return `<dialog id="reference-viewer" class="reference-viewer" aria-labelledby="reference-viewer-title" aria-describedby="reference-viewer-help"><header><h2 id="reference-viewer-title">Painting reference</h2><button id="reference-close" aria-label="Close reference">Close ×</button></header><p id="reference-viewer-help">Zoom to see the details. Scroll or swipe to move around the image.</p><div class="reference-viewer-tools" role="group" aria-label="Reference zoom"><button id="reference-fit">Fit</button><button id="reference-out" aria-label="Zoom out">−</button><output id="reference-zoom" aria-live="polite">100%</output><button id="reference-in" aria-label="Zoom in">+</button></div><div id="reference-viewport" class="reference-viewport" tabindex="0" aria-label="Painting image. Use arrow keys or swipe to scroll."><img id="reference-image" alt="" hidden></div><p id="reference-image-status" role="status"></p></dialog>`;}
function openReferenceViewer(id,opener){
 const reference=drawingPhotoReference(id),dialog=$('#reference-viewer');if(!reference||!dialog||dialog.open)return;
 finishDrawingStroke();stopSpeech();dialog.reference=reference;dialog.referenceOpener=opener||document.activeElement;dialog.referenceZoom=1;
 $('#reference-viewer-title').textContent=reference.title;
 const img=$('#reference-image');img.alt=reference.alt;img.width=reference.width;img.height=reference.height;img.hidden=false;
 $('#reference-image-status').textContent='';img.src=reference.image;
 dialog.showModal();sizeReferenceViewer(true);$('#reference-close').focus({preventScroll:true});
}
function sizeReferenceViewer(reset=false){
 const dialog=$('#reference-viewer');if(!dialog?.open||!dialog.reference)return;
 const viewport=$('#reference-viewport'),image=$('#reference-image'),r=dialog.reference;
 const fit=Math.max(1,Math.min(viewport.clientWidth-32,(viewport.clientHeight-32)*r.width/r.height));
 image.style.width=Math.round(fit*dialog.referenceZoom)+'px';image.style.height='auto';
 $('#reference-zoom').textContent=Math.round(dialog.referenceZoom*100)+'%';
 $('#reference-out').disabled=dialog.referenceZoom<=1;$('#reference-in').disabled=dialog.referenceZoom>=4;
 if(reset){viewport.scrollLeft=0;viewport.scrollTop=0;}
}
function bindReferenceViewer(){
 disposeReferenceViewer();const dialog=$('#reference-viewer');if(!dialog)return;
 const image=$('#reference-image'),close=$('#reference-close'),fit=$('#reference-fit'),minus=$('#reference-out'),plus=$('#reference-in');
 const closeDialog=()=>dialog.close(),fitImage=()=>{dialog.referenceZoom=1;sizeReferenceViewer(true);};
 const zoom=delta=>{dialog.referenceZoom=Math.max(1,Math.min(4,dialog.referenceZoom+delta));sizeReferenceViewer();};
 const zoomIn=()=>zoom(.5),zoomOut=()=>zoom(-.5),resize=()=>sizeReferenceViewer();
 const restore=()=>{const opener=dialog.referenceOpener;dialog.referenceOpener=null;if(opener?.isConnected)opener.focus({preventScroll:true});else $('#guide-change')?.focus({preventScroll:true});};
 const fail=()=>{$('#reference-image-status').textContent='The reference image could not load. Reopen it to try again.';};
 close.addEventListener('click',closeDialog);fit.addEventListener('click',fitImage);plus.addEventListener('click',zoomIn);minus.addEventListener('click',zoomOut);dialog.addEventListener('close',restore);
 image.addEventListener('load',resize);image.addEventListener('error',fail);window.addEventListener('resize',resize);
 disposeReferenceViewer=()=>{
  close.removeEventListener('click',closeDialog);fit.removeEventListener('click',fitImage);plus.removeEventListener('click',zoomIn);minus.removeEventListener('click',zoomOut);dialog.removeEventListener('close',restore);
  image.removeEventListener('load',resize);image.removeEventListener('error',fail);window.removeEventListener('resize',resize);
  if(dialog.open)dialog.close();dialog.reference=null;dialog.referenceOpener=null;disposeReferenceViewer=()=>{};
 };
}
;
