function drawingGuideExample(id){return traditionalReference(id)||DRAWING_EXAMPLES.find(x=>x.id===id);}
let drawingGuideState=null;
let guideListeningKey=null;
let guideReferenceTab='original';
function guideReferenceMarkup(example){
 const g=getDrawingGuide(),hasStudy=!!drawingPhotoReference(g.exampleId);
 const photo=drawingPhotoReference(g.exampleId)?drawingPhotoMarkup(example):'';
 const sketch=`<figure class="inspiration-reference">${guideSketch()}<figcaption>${hasStudy?'Simplified drawing study / Step '+(g.step+1):'One possible direction. Keep your own.'}</figcaption></figure>`;
 if(!hasStudy)return sketch;
 return `<div class="guide-reference-tabs" role="tablist" aria-label="Drawing reference">${[['original','Original print'],['example','Step example']].map(([id,label])=>`<button type="button" role="tab" id="guide-reference-${id}" data-guide-reference="${id}" aria-controls="guide-panel-${id}" aria-selected="${guideReferenceTab===id}" tabindex="${guideReferenceTab===id?0:-1}">${label}</button>`).join('')}</div>${[['original',photo],['example',sketch]].map(([id,content])=>`<div id="guide-panel-${id}" class="guide-reference-panel" role="tabpanel" aria-labelledby="guide-reference-${id}" tabindex="0" ${guideReferenceTab!==id?'hidden':''}>${content}</div>`).join('')}`;
}
function selectGuideReference(id){
 if(!['original','example'].includes(id))return;
 guideReferenceTab=id;
 for(const value of ['original','example']){
  const tab=$('#guide-reference-'+value),panel=$('#guide-panel-'+value);
  if(!tab||!panel)continue;
  tab.setAttribute('aria-selected',String(value===id));
  tab.setAttribute('tabindex',value===id?'0':'-1');
  panel.hidden=value!==id;
 }
 $('#guide-reference-'+id)?.focus({preventScroll:true});
}
function getDrawingGuide(){
 if(drawingGuideState)return drawingGuideState;
 const saved=safeGet('dongho-drawing-guide',{})||{};
 const legacy={bird:'garden-bird',garden:'blooming-garden',own:'own'};
 let exampleId=saved.exampleId||legacy[saved.topic]||null;
 const migrated=LEGACY_EXAMPLE_IDS[exampleId];if(migrated)exampleId=migrated[0];
 if(exampleId!=='own'&&!drawingGuideExample(exampleId))exampleId=null;
 const example=drawingGuideExample(exampleId);
 const savedMood=INSPIRATION_MOODS.some(x=>x.id===saved.moodId)?saved.moodId:null;
 const moodId=saved.pickerOpen&&savedMood?savedMood:migrated?.[1]||savedMood||Object.keys(PHOTO_MOOD_IDS).find(id=>PHOTO_MOOD_IDS[id].includes(exampleId))||null;
 const collection=['tradition','free','own'].includes(saved.collection)?saved.collection:traditionalReference(exampleId)?'tradition':exampleId==='own'?'own':exampleId||savedMood?'free':'tradition';
 drawingGuideState={version:4,collection,moodId,referenceMood:INSPIRATION_MOODS.some(m=>m.id===saved.referenceMood)?saved.referenceMood:moodId,exampleId,step:migrated?0:Number.isInteger(saved.step)?Math.max(0,Math.min(4,saved.step)):0,collapsed:!!saved.collapsed,pickerOpen:typeof saved.pickerOpen==='boolean'?saved.pickerOpen:!exampleId};
 return drawingGuideState;
}
function drawingLesson(){const g=getDrawingGuide();return (drawingGuideExample(g.exampleId)?.steps||OWN_DRAWING_STEPS)[g.step];}
